import { useState, useEffect } from "react";
import Confetti from "react-confetti";
import gsap from "gsap";
import Cake from "../../components/cake/Cake";
import "./HBD.css";
import img0 from "../../images/0.jpg";
import img1 from "../../images/1.jpg";
import img2 from "../../images/2.jpg";
import img3 from "../../images/3.jpg";
import img4 from "../../images/4.jpg";
import img5 from "../../images/5.jpg";
import img6 from "../../images/6.jpg";
import img7 from "../../images/7.jpg";
import img8 from "../../images/8.jpg";
import img9 from "../../images/9.jpg";
import img10 from "../../images/10.jpg";


const defaultData = [
    { id: 0, image: img0, text: "🍒 22 SEP 2025" },
    { id: 1, image: img1, text: "💄 10 JUL 2025" },
    { id: 2, image: img7, text: "🍎 18 SEP 2025" },
    { id: 3, image: img3, text: "🌊 22 AUG 2025" },
    { id: 4, image: img4, text: "🌙 10 AUG 2025" },
    { id: 5, image: img5, text: "🌻 17 OCT 2024" },
    { id: 6, image: img6, text: "🌳 19 JUL 2025" },
    { id: 7, image: img2, text: "🧁 1 SEP 2025" },
    { id: 8, image: img8, text: "📸 15 SEP 2025" },
    { id: 9, image: img9, text: "🧸 11 JUL 2025" },
    { id: 10, image: img10, text: "☂️ 21 FEB 2024" },
];

const HBD = () => {
    const [content, setContent] = useState([]);

    useEffect(() => {
        const saved = localStorage.getItem("birthdayContent");
        if (saved) {
            setContent(JSON.parse(saved));
        } else {
            setContent(defaultData);
            localStorage.setItem("birthdayContent", JSON.stringify(defaultData));
        }
        gsap.to(".have-delay", {
            duration: 5,
            delay: 8,
            opacity: 1,
        });
    }, []);

    return (
        <div className="hbd-container">
            <Cake />
            <div className="have-delay">
                <Confetti
                    height={
                        window.innerWidth > 768
                            ? window.innerHeight
                            : window.innerHeight * 5.5
                    }
                    numberOfPieces={window.innerWidth > 768 ? 150 : 450}
                    gravity={0.05}
                />
                {
                    content.map((item, index) => (
                        <figure key={item.id} className={`swing swing${index}`}>
                            <img src={item.image} alt="" width="110" />
                            <span>{item.text}</span>
                        </figure>
                    ))
                }
            </div>
        </div>
    );
};


export default HBD;
