import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./UpdateContent.css";


const UpdateContent = () => {
    const [content, setContent] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        document.body.classList.add("update-page");
        return () => {
            document.body.classList.remove("update-page");
        };
    }, []);

    useEffect(() => {
        const saved = localStorage.getItem("birthdayContent");
        if (saved) {
            setContent(JSON.parse(saved));
        }
    }, []);

    const handleTextChange = (index, value) => {
        const updated = [...content];
        updated[index].text = value;
        setContent(updated);
    };

    const handleImageChange = (index, file) => {
        const reader = new FileReader();
        reader.onloadend = () => {
            const updated = [...content];
            updated[index].image = reader.result;
            setContent(updated);
        };
        reader.readAsDataURL(file);
    };

    const handleSave = () => {
        localStorage.setItem("birthdayContent", JSON.stringify(content));
        navigate("/");
    };

    return (
        <div className="update-container">
            <h2 className="update-title">Update Memories ✨</h2>
            <div className="update-grid">
                {
                    content.map((item, index) => (
                        <div key={item.id} className="update-card">
                            <img
                                src={item.image}
                                alt=""
                                className="update-preview"
                            />
                            <input
                                type="text"
                                className="update-input"
                                value={item.text}
                                onChange={(e) => handleTextChange(index, e.target.value)}
                                placeholder="Edit caption..."
                            />
                            <input
                                type="file"
                                className="update-file"
                                onChange={(e) =>
                                    handleImageChange(index, e.target.files[0])
                                }
                            />
                        </div>
                    ))
                }
            </div>
            <div className="save-wrapper">
                <button className="save-btn" onClick={handleSave}>
                    Save Changes
                </button>
            </div>
        </div>
    );
};


export default UpdateContent;
